function validate(scope){const problems=[];const seen=new Set();scope.querySelectorAll('input,select,textarea').forEach(el=>{if(el.disabled||el.closest('[hidden]')||el.type==='hidden'||el.name==='website')return;if(el.type==='file'){const m=fileProblem(el);setError(el,m);if(m)problems.push({el,label:fieldLabel(el),msg:m});return;}if(el.type==='radio'){if(!el.required||seen.has(el.name))return;seen.add(el.name);if(!scope.querySelector(`[name="${el.name}"]:checked`)){const m=tr('Choisissez une option.','Please choose an option.');setError(el,m);problems.push({el,label:el.closest('fieldset')?.querySelector('legend')?.textContent||el.name,msg:m});}else setError(el,'');return;}if(el.type==='checkbox'){if(el.required&&!el.checked){const m=tr('Cette case doit être cochée.','This box must be ticked.');setError(el,m);problems.push({el,label:fieldLabel(el),msg:m});}else if(el.required)setError(el,'');return;}const ok=el.checkValidity();const m=ok?'':el.validity.valueMissing?tr('Veuillez compléter ce champ.','Please complete this field.'):tr('Veuillez vérifier cette information.','Please check this information.');setError(el,m);if(!ok)problems.push({el,label:fieldLabel(el),msg:m});});return problems;}
